# Phase 1: Days 01 to 05 Data
import json

def get_days_01_to_05():
    questions = []

    # Helper to add 45 questions
    def add_day(track, day, topic_base, easy_list, med_list, hard_list):
        assert len(easy_list) == 15, f"{day} Easy list has {len(easy_list)}, expected 15"
        assert len(med_list) == 18, f"{day} Med list has {len(med_list)}, expected 18"
        assert len(hard_list) == 12, f"{day} Hard list has {len(hard_list)}, expected 12"
        
        for idx, item in enumerate(easy_list, 1):
            q_id = f"{day.lower().replace(' ', '_')}_{idx:03d}"
            questions.append({
                "id": q_id, "track": track, "day": day, "topic": f"{topic_base} ({item[0]})",
                "difficulty": "Easy", "question": item[1], "options": item[2],
                "correct_index": item[3], "correct_answer": item[2][item[3]],
                "explanation": item[4], "slide_ref": item[5]
            })
        for idx, item in enumerate(med_list, 16):
            q_id = f"{day.lower().replace(' ', '_')}_{idx:03d}"
            questions.append({
                "id": q_id, "track": track, "day": day, "topic": f"{topic_base} ({item[0]})",
                "difficulty": "Medium", "question": item[1], "options": item[2],
                "correct_index": item[3], "correct_answer": item[2][item[3]],
                "explanation": item[4], "slide_ref": item[5]
            })
        for idx, item in enumerate(hard_list, 34):
            q_id = f"{day.lower().replace(' ', '_')}_{idx:03d}"
            questions.append({
                "id": q_id, "track": track, "day": day, "topic": f"{topic_base} ({item[0]})",
                "difficulty": "Hard", "question": item[1], "options": item[2],
                "correct_index": item[3], "correct_answer": item[2][item[3]],
                "explanation": item[4], "slide_ref": item[5]
            })

